import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import './css/Login.css';
import logoImage from '../assets/aqi.webp';

// --- START: CSRF TOKEN HELPER ---
// This function reads the security token from your browser's cookies
function getCsrfToken() {
  let cookieValue = null;
  if (document.cookie && document.cookie !== '') {
    const cookies = document.cookie.split(';');
    for (let i = 0; i < cookies.length; i++) {
      const cookie = cookies[i].trim();
      // Does this cookie string begin with the name we want?
      if (cookie.substring(0, 10) === 'csrftoken=') {
        cookieValue = decodeURIComponent(cookie.substring(10));
        break;
      }
    }
  }
  return cookieValue;
}
// --- END: CSRF TOKEN HELPER ---


function Login() {
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [isMobileView, setIsMobileView] = useState(window.innerWidth <= 768);
  const navigate = useNavigate();

  const API_BASE_URL =
    process.env.NODE_ENV === 'production'
      ? 'https://airaware-app-gcw7.onrender.com'
      : 'http://localhost:8000';

  useEffect(() => {
    const handleResize = () => setIsMobileView(window.innerWidth <= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError('');
    setSuccess('');
  };

  // --- START: CORRECTED SUBMIT FUNCTION ---
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      console.log("➡️ Sending login request...");

      // FIX 1: Get the CSRF token
      const csrftoken = getCsrfToken();

      const response = await fetch(`${API_BASE_URL}/api/login/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          // FIX 2: Add the token to the request header
          'X-CSRFToken': csrftoken,
        },
        body: JSON.stringify({
          username: formData.username,
          password: formData.password
        }),
        // FIX 3: Tell fetch to include cookies (like the token)
        credentials: 'include',
      });

      console.log("✅ Response status:", response.status);

      const data = await response.json();
      console.log("📦 Response data:", data);

      if (response.ok && data.success) {
        console.log("🎯 Login successful, navigating to:", data.redirect_to,data.user);

        localStorage.setItem('user', JSON.stringify(data.user));

        if (data.redirect_to === '/health-assessment') {
            console.log('Navigating to health assessment');
            navigate('/health-assessment');
          } else if (data.redirect_to === '/dashboard') {
            console.log('Navigating to dashboard');
            navigate('/dashboard');
          } else {
            // Fallback logic based on has_health_assessment
            if (data.user.has_health_assessment) {
              console.log('Fallback: Navigating to dashboard');
              navigate('/dashboard');
            } else {
              console.log('Fallback: Navigating to health assessment');
              navigate('/health-assessment');
            }
          }
      } else {
        console.log("⚠️ Login failed:", data.error || data.message);
        setError(data.error || 'Login failed. Please try again.');
      }
    } catch (err) {
      console.error("❌ Network error:", err);
      // This specifically catches the HTML-parsing-as-JSON error
      if (err instanceof SyntaxError) {
        setError('Login failed: Server rejected the request.');
      } else {
        setError('Network error. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };
  // --- END: CORRECTED SUBMIT FUNCTION ---

  return (
    <div className="login-page">
      <nav className="navbar">
        <div className="navbar-content">
          <Link to="/" className="navbar-brand">
            <img
              src={logoImage}
              alt="AirAware"
              width={isMobileView ? '32' : '40'}
              height={isMobileView ? '32' : '40'}
            />
            AirAware
          </Link>
        </div>
      </nav>

      <section className="login-section">
        <div className="login-container">
          <div className="login-header">
            <h2>👤 User Login</h2>
            <p>Enter your credentials to continue</p>
          </div>

          {(success || error) && (
            <div className={`toast-notification ${success ? 'toast-success' : 'toast-error'}`}>
              <span>{success || error}</span>
              <button className="toast-close" onClick={() => { setSuccess(''); setError(''); }}>×</button>
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="username">Username</label>
              <input
                type="text"
                id="username"
                name="username"
                value={formData.username}
                onChange={handleChange}
                placeholder="Enter username"
                required
                disabled={loading}
              />
            </div>

            <div className="form-group">
              <label htmlFor="password">Password</label>
              <input
                type="password"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Enter password"
                required
                disabled={loading}
              />
            </div>

            <button
              type="submit"
              className="btn-primary"
              disabled={loading}
            ><Link to="/dashboard"></Link>
              {loading ? 'Logging in...' : 'Login'}
            </button>

            <div className="login-footer">
              <p>
                Don’t have an account? <Link to="/signup">Sign Up</Link>
              </p>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
}

export default Login;
